        // .NET 9: DropDownControl parameter is now non-nullable.
        // Guard against passing null to avoid ArgumentNullException.
        var control = CreateEditorControl(value);
        if (control is null)
            return value;

        editorService.DropDownControl(control);
        return control.Tag;
    }

    private Control? CreateEditorControl(object? value)
    {
        // Placeholder: return null if no valid editor control can be created
        if (value is null)
            return null;

        var listBox = new ListBox();
        listBox.Tag = value;
        return listBox;
    }
}

